def max_sum_list(lists):
    if not lists:
        return []
    max_sum = float('-inf')
    max_list = []
    for lst in lists:
        current_sum = sum(lst)
        if current_sum > max_sum:
            max_sum = current_sum
            max_list = lst
    return max_list
```

